fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target_width = width as usize; // Convert width to usize for indexing

    if orig_len >= target_width {
        // If original length is greater than or equal to target width, return orig
        return orig;
    }

    // Create a new vector with the target width, filled with the fill character
    let mut result = vec![fillchar; target_width];

    // Copy the original characters to the end of the result vector
    let start_index = target_width - orig_len; // Calculate where to start copying
    result[start_index..].copy_from_slice(&orig);

    result
}